/*
 * A328014  Numbers whose powerful part (A057521) is larger than their
 *          powerfree part (A055231).
 * https://oeis.org/A328014
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 56, u16 n <= 4030, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A328014: Numbers whose powerful part (A057521) is larger
 * than their powerfree part (A055231).  The terms are generated by a
 * brute‑force search: each integer is tested, and the n‑th valid
 * integer is returned. */

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <math.h>

/* ----------   Prime list helpers   ---------- */

static uint32_t *primes = NULL;
static size_t primes_cnt = 0;
static size_t primes_cap = 0;

/* Ensure that the prime list contains all primes up to |limit|. */
static void ensure_primes_up_to(uint32_t limit)
{
    if (limit <= (primes_cnt ? primes[primes_cnt - 1] : 1u))
        return;

    if (!primes) {
        primes_cap = 128;
        primes = (uint32_t *)malloc(primes_cap * sizeof(uint32_t));
    }
    while (primes_cap <= (size_t)limit) {
        primes_cap <<= 1;
        uint32_t *tmp = (uint32_t *)realloc(primes, primes_cap * sizeof(uint32_t));
        if (!tmp) {
            free(primes);
            primes = NULL;
            primes_cnt = 0;
            primes_cap = 0;
            return;
        }
        primes = tmp;
    }

    if (!primes_cnt) {
        primes[primes_cnt++] = 2;
    }
    uint32_t candidate = primes[primes_cnt - 1] + 1;
    for (; candidate <= limit; ++candidate) {
        bool is_prime = true;
        uint32_t r = (uint32_t)sqrt((double)candidate);
        for (size_t i = 0; i < primes_cnt && primes[i] <= r; ++i) {
            if (candidate % primes[i] == 0) {
                is_prime = false;
                break;
            }
        }
        if (is_prime) {
            primes[primes_cnt++] = candidate;
        }
    }
}

/* ----------   Sequence test   ---------- */

/* Return true if n satisfies that its powerful part > its powerfree part. */
static bool test_seq(uint64_t n)
{
    if (n <= 1U) return false;

    uint64_t powerful = 1;
    uint64_t powerfree = 1;
    uint64_t temp = n;

    uint32_t sqrt_limit = (uint32_t)sqrt((double)temp);
    ensure_primes_up_to(sqrt_limit);

    for (size_t i = 0; i < primes_cnt && (uint64_t)primes[i] * primes[i] <= temp; ++i) {
        uint32_t p = primes[i];
        if (temp % p) continue;
        int cnt = 0;
        while (temp % p == 0) {
            temp /= p;
            ++cnt;
        }
        if (cnt >= 2) {
            /* multiply p cnt times (i.e. p^cnt) */
            for (int k = 0; k < cnt; ++k) powerful *= (uint64_t)p;
        } else { /* cnt == 1 */
            powerfree *= (uint64_t)p;
        }
    }
    if (temp > 1U) { /* remaining prime factor with exponent 1 */
        powerfree *= temp;
    }

    return powerful > powerfree;
}

/* ----------   Public sequence function   ---------- */

/* a(n) – nth term of A328014 (1‑indexed). */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* undefined, but guard */

    idx_t count = 0;
    uint64_t candidate = 2;        /* start from 2 */

    while (count < n) {
        if (test_seq(candidate)) {
            ++count;
            if (count == n)
                return (seq_t)candidate;
        }
        ++candidate;
    }
    /* unreachable – but keep the compiler happy */
    return (seq_t)candidate;
}
